package com.hkdn.backend.service;
import com.hkdn.backend.entity.*;import com.hkdn.backend.repository.BlockchainTransactionRepository;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service public class BlockchainService {private final BlockchainGateway gateway;private final BlockchainTransactionRepository transactions;public BlockchainService(BlockchainGateway gateway,BlockchainTransactionRepository transactions){this.gateway=gateway;this.transactions=transactions;}
 @Transactional public BlockchainTransaction record(Certificate certificate){BlockchainTransaction tx=new BlockchainTransaction();tx.setCertificate(certificate);tx.setContentHash(certificate.getContentHash());tx.setNetwork("configured");if(!gateway.available()){tx.setStatus(BlockchainStatus.UNAVAILABLE);tx.setErrorMessage("Blockchain integration is not configured");return transactions.save(tx);}Optional<String> hash=gateway.recordHash(certificate.getContentHash());if(hash.isPresent()){tx.setStatus(BlockchainStatus.CONFIRMED);tx.setTransactionHash(hash.get());tx.setConfirmedAt(java.time.Instant.now());}else{tx.setStatus(BlockchainStatus.FAILED);tx.setErrorMessage("Blockchain transaction was not confirmed");}return transactions.save(tx);}
 @Transactional(readOnly=true) public Optional<Boolean> verify(String hash){return gateway.hasHash(hash);}
 public boolean available(){return gateway.available();}}
